}

/* ==  亮色背景覆盖层（删掉这一段即恢复暗色）== */
:root {
  /* 对方：亮色毛玻璃（纯白壁纸看不清气泡的话，换成 rgba(120,120,128,0.16) 的灰调） */
  --bubble-them-bg: rgba(255, 255, 255, 0.62);
  --bubble-them-color: #111;
  /* 对方液态描边：左上白高光，右下淡灰收边 */
