  /* 6. 特殊部件日间色 */
  --card-bg: #ffffff;
  --card-border: rgba(0, 0, 0, 0.08);
  --btn-back-bg: #f2f2f7;
  --knob-holder-bg: #e8e8ed;
  --knob-light: rgba(255, 255, 255, 0.85);
