  letter-spacing: -0.2px !important; box-shadow: 0 2px 8px rgba(0, 122, 255, 0.3) !important; z-index: 3 !important;
}

/* 蓝底状态：中断/接通中 */
.msg-videocall-card.connected,
.msg-videocall-card:has([class*="end"]),
.msg-videocall-card:has([class*="finish"]),
.msg-videocall-card:has([class*="interrupt"]) {
