.stop-btn-custom {
  width: 42px !important; height: 42px !important; 
  min-width: 42px !important; max-width: 42px !important;
  border-radius: 50% !important; 
  background: rgba(120, 120, 128, 0.25) !important;
  backdrop-filter: blur(16px) !important;
  -webkit-backdrop-filter: blur(16px) !important;
  border: 1px solid rgba(255, 255, 255, 0.15) !important;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15) !important;
  display: flex !important; align-items: center !important; justify-content: center !important;
  margin-left: 8px !important; padding: 0 !important; 
  z-index: 3 !important;
}
.stop-btn-custom:active { transform: scale(0.92); }
.stop-btn-custom svg { display: none !important; }
.stop-btn-custom::after {
  content: "" !important; width: 20px !important; height: 20px !important;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 24 24' xmlns='http://www.w3.org/2000/svg'%3E%3Cstyle%3Eline%7Bstroke:%238e8e93;stroke-width:2.4;stroke-linecap:round%7D%3C/style%3E%3Cline x1='12' y1='2.5' x2='12' y2='6.5' opacity='1'/%3E%3Cline x1='18.72' y1='5.28' x2='15.89' y2='8.11' opacity='.87'/%3E%3Cline x1='21.5' y1='12' x2='17.5' y2='12' opacity='.75'/%3E%3Cline x1='18.72' y1='18.72' x2='15.89' y2='15.89' opacity='.62'/%3E%3Cline x1='12' y1='21.5' x2='12' y2='17.5' opacity='.5'/%3E%3Cline x1='5.28' y1='18.72' x2='8.11' y2='15.89' opacity='.37'/%3E%3Cline x1='2.5' y1='12' x2='6.5' y2='12' opacity='.25'/%3E%3Cline x1='5.28' y1='5.28' x2='8.11' y2='8.11' opacity='.12'/%3E%3C/svg%3E") !important;
  background-size: contain !important; background-repeat: no-repeat !important;
  animation: ios8BladeIndicator 0.8s steps(8, end) infinite !important;
