/* ===== 气泡 ===== */
:root{
  --nj-them-bg:#eeeeee;     /* 对方气泡 */
  --nj-them-color:#1a1a1a;  /* 对方文字 */
  --nj-me-bg:#1e1e1e;       /* 我方气泡 */
