/* ===== 引用 ===== */
:root{
  --nj-q-name:#776d69;    /* 「回复 我」颜色 */
  --nj-q-text:#847b77;    /* 被引用的文字颜色 */
  --nj-q-line:#dbdbdb;    /* 分隔线颜色 */
}

/* 我方气泡里的引用颜色（跟着配色走） */
:root{
  --nj-q-me-name:rgba(255,255,255,.78);
  --nj-q-me-text:rgba(255,255,255,.58);
  --nj-q-me-line:rgba(255,255,255,.2);
}
:is(.msg-me,.bubble-me-custom) .msg-reply-block{
  --nj-q-name:var(--nj-q-me-name);
  --nj-q-text:var(--nj-q-me-text);
  --nj-q-line:var(--nj-q-me-line);
}

/* 整块：去底色，上下排列，下面一条细线 */
.msg-reply-block{
  display:flex !important;
  flex-direction:column !important;
  align-items:flex-start !important;
  gap:0 !important;
  width:100%;
  background:none !important;
  border:none !important;
  border-bottom:1px solid var(--nj-q-line) !important;
  border-radius:0 !important;
  box-shadow:none !important;
  padding:0 0 8px !important;
  margin:0 0 8px !important;
  max-width:none !important;
}

/* 名字：加粗，前面补「回复」两个字 */
.msg-reply-block-name{
  font-size:13px !important;
  font-weight:700 !important;
  line-height:18px !important;
  color:var(--nj-q-name) !important;
}
.msg-reply-block-name::before{
  content:"回复\00a0";
}

/* 被引用的文字 */
